/** Targets remain in authored prompts for server complexity guidance. The UI
 * presents them once, through Desired complexity, instead of repeating the
 * author's Target line in the description. Keep subsequent paragraphs. */
export function descriptionText(prompt: string): string {
  return prompt.replace(/(?:^|[\t ]+)Target:[^\n]*(?:\n|$)/gm, '\n').trim();
}

/** Preserve inline code verbatim, grouping long authored prose at sentence
 * boundaries. No content is removed or generated by this presentation step. */
export function descriptionParagraphs(text: string): string[] {
  const paragraphs: string[] = [];
  for (const block of text.split(/\n\s*\n/)) {
    const tokens = block.split(/(`[^`]*`)/g);
    const sentences: string[] = [];
    let sentence = '';
    for (let index = 0; index < tokens.length; index++) {
      if (index % 2) { sentence += tokens[index]; continue; }
      const pieces = tokens[index].split(/(?<=[.!?])\s+(?=[A-Z])/);
      pieces.forEach((piece, i) => { sentence += piece; if (i < pieces.length - 1) { sentences.push(sentence); sentence = ''; } });
    }
    if (sentence.trim()) sentences.push(sentence);
    let paragraph = '';
    for (const one of sentences) {
      if (paragraph && paragraph.length + one.length > 240) { paragraphs.push(paragraph.trim()); paragraph = ''; }
      paragraph += (paragraph ? ' ' : '') + one;
    }
    if (paragraph.trim()) paragraphs.push(paragraph.trim());
  }
  return paragraphs;
}
